package core

// The same quiet folio vocabulary is used for full, shared and incident reports.
const reportStyle = `
:root{color-scheme:light;--ink:#202d2c;--muted:#5b645c;--line:#daded4;--paper:#fffef9;--wash:#f2f3ec;--accent:#46605b;--accent-2:#46605b;--critical:#873f35;--warn:#9b682e;--ok:#46605b;--memory:#46605b;--violet:#46605b}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.65 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:56px 64px 90px;counter-reset:folio}header{padding-bottom:20px;border-bottom:1px solid var(--ink)}.kicker,header>small{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--accent);font-weight:650}h1{margin:22px 0 0;font:400 3rem/1.12 Georgia,Palatino,serif;max-width:23em;overflow-wrap:anywhere}.lead{font:400 1.18rem/1.65 Georgia,Palatino,serif;max-width:46em}.meta,.muted,small{color:var(--muted)}.facts,.grid{list-style:none;display:flex;flex-wrap:wrap;gap:0;margin:28px 0 0;padding:0}.fact,.card{padding:12px 24px 8px 0;flex:1;min-width:145px;border:0;background:transparent;font-size:12px;color:var(--muted)}.fact span,.card b{display:block;font:400 2.1rem/1.2 Georgia,serif;color:var(--ink)}.fact small{display:block}.fact+.fact,.card+.card{padding-left:24px;border-left:1px solid var(--line)}nav{display:flex;flex-wrap:wrap;gap:8px 22px;margin:0 0 32px;padding:14px 0;border-bottom:1px solid var(--line)}nav a{font-size:12px;font-weight:600;text-decoration:none}h2{counter-increment:folio;margin:48px 0 18px;font:400 1.55rem/1.3 Georgia,serif;border-bottom:1px solid var(--line);padding-bottom:12px}h2:before{content:counter(folio,decimal-leading-zero) " / ";font:500 11px system-ui;color:var(--warn);letter-spacing:.08em;margin-right:12px}h3{margin:24px 0 10px;font-size:14px;font-weight:650}p,li{overflow-wrap:anywhere}.ok{color:var(--ok);font-weight:650}.warn{color:var(--warn);font-weight:650}.critical{color:var(--critical);font-weight:650}dl{display:grid;grid-template-columns:minmax(140px,220px) 1fr;margin:18px 0}dt,dd{margin:0;padding:9px 0;border-bottom:1px solid var(--line)}dt{color:var(--muted);padding-right:20px;font-size:12px}dd{overflow-wrap:anywhere}table{border-collapse:collapse;width:100%;margin:16px 0;font-size:12px}th,td{text-align:left;vertical-align:top;border-bottom:1px solid var(--line);padding:10px 12px 10px 0;overflow-wrap:anywhere}th{font-size:10px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);border-top:1px solid var(--ink)}tr:hover td{background:var(--wash)}code,.mono{font:12px/1.65 ui-monospace,monospace;overflow-wrap:anywhere}code{white-space:pre-wrap}.note,.notice{padding:14px 18px;border-left:2px solid var(--warn);background:var(--wash);margin:20px 0;font-size:13px}.group{padding:20px 0;border-bottom:1px solid var(--line)}.group header{display:flex;justify-content:space-between;gap:24px;border:0;padding:0}.tag,.pill{display:inline-block;font-size:10px;text-transform:uppercase;letter-spacing:.05em;padding:1px 7px;border:1px solid var(--line);color:var(--muted)}.pill-confirmed{color:var(--ok)}.pill-needs-review{color:var(--warn)}.pill-rejected{color:var(--critical)}a{color:var(--accent);text-underline-offset:3px}label{display:block;margin-top:22px;font-size:12px;color:var(--muted)}input,select,button{font:inherit;background:var(--paper);color:var(--ink);border:1px solid var(--line);padding:8px 12px;border-radius:0}input[type=search]{width:min(100%,430px);margin:8px 0}button{cursor:pointer;font-size:12px}button:disabled{opacity:.45;cursor:default}input:focus,button:focus,a:focus{outline:2px solid var(--accent);outline-offset:3px}.pager{display:flex;gap:12px;align-items:center;margin:12px 0;font-size:12px;color:var(--muted)}footer{margin-top:56px;padding-top:18px;border-top:1px solid var(--ink);font-size:12px;color:var(--muted)}.figure-grid{display:grid;grid-template-columns:1fr 1fr;gap:36px}figure{margin:0}figcaption{font-size:12px;font-weight:650;margin-bottom:14px}.bar-row{display:grid;grid-template-columns:minmax(95px,1fr) 2fr 36px;gap:14px;align-items:center;font-size:11px;margin:9px 0}.bar-track{height:4px;background:var(--wash)}.bar-fill{display:block;height:4px;background:var(--accent)}.figure-note{font-size:11px;color:var(--muted);margin:18px 0}.table-wrap{overflow:auto}.reading-edition{font-size:12px;margin-top:18px}
@media(max-width:720px){main{padding:28px 22px 60px}h1{font-size:2.2rem}.figure-grid{grid-template-columns:1fr}.group header{display:block}dl{grid-template-columns:120px 1fr}.fact{min-width:120px}.table-wrap{overflow:auto}}
@page{size:A4;margin:18mm 16mm}@media print{nav,label,.pager,button,input,.reading-edition{display:none}body{background:white;font-size:10pt}main{max-width:none;padding:0}h1{font-size:28pt}h2{break-after:avoid;margin-top:24pt}h3{break-after:avoid}th{display:table-cell}thead{display:table-header-group}tr{break-inside:avoid}table{font-size:8pt}.group,.note,figure{break-inside:avoid}.figure-grid{display:block}.bar-fill{print-color-adjust:exact}.table-wrap{overflow:visible}a{color:inherit;text-decoration:none}tr:hover td{background:none}details{display:block}details>*{display:block}}
`
